<script setup lang="ts">
import { ChevronDown, CornerDownRight, Download, GitBranch, LayoutDashboard, ListTree, MoreHorizontal, Pencil, Plus, Redo2, Undo2, Upload } from '@lucide/vue';
import { t as uiText } from '../i18n';
const props = defineProps<{ hasMaps: boolean; selected: boolean; selectedCount: number; outline: boolean; folded: boolean; canUndo: boolean; canRedo: boolean; canConvert?: boolean; busy: boolean; layout?: string; saving?: boolean }>();
const emit = defineEmits<{ (event: 'action', action: string): void }>();
function action(value: string, event?: Event) { emit('action', value); (event?.target as Element | null)?.closest('details')?.removeAttribute('open'); }
</script>
<template>
  <nav class="mind-map-toolbar" aria-label="思维导图编辑工具">
    <button v-if="!hasMaps" class="map-create" type="button" :disabled="busy" @click="action('create')"><GitBranch :size="16" /><span>添加思维导图</span></button>
    <div v-else class="map-mode" role="group" :aria-label="uiText('画板显示方式')"><button type="button" :aria-pressed="!outline" @click="action('graph')"><LayoutDashboard :size="15" /><span>{{ uiText('画布') }}</span></button><button type="button" :aria-pressed="outline" @click="action('outline')"><ListTree :size="15" /><span>大纲</span></button></div>
    <span class="map-divider"></span>
    <button type="button" :disabled="!canUndo || busy || saving" aria-label="撤销画板修改" title="撤销 Ctrl / ⌘ Z" @click="action('undo')"><Undo2 :size="16" /></button>
    <button type="button" :disabled="!canRedo || busy || saving" aria-label="重做画板修改" title="重做 Ctrl / ⌘ Shift Z" @click="action('redo')"><Redo2 :size="16" /></button>
    <template v-if="selected"><span class="map-divider"></span><button type="button" :disabled="busy" @click="action('child')"><Plus :size="15" /><span>子主题</span></button><button type="button" :disabled="busy" @click="action('sibling')"><CornerDownRight :size="15" /><span>同级</span></button><button type="button" :disabled="busy" aria-label="编辑所选主题" @click="action('edit')"><Pencil :size="14" /><span class="map-desktop-label">编辑</span></button><button type="button" @click="action('fold')"><ChevronDown :size="15" /><span>{{ folded ? '展开' : '折叠' }}</span></button></template>
    <span v-if="selectedCount > 1" class="map-selected-count">已选 {{ selectedCount }} 项</span><span class="map-toolbar-spacer"></span>
    <details class="map-more"><summary aria-label="更多导图操作"><MoreHorizontal :size="18" /></summary><div class="map-menu">
      <template v-if="selected"><button type="button" @click="action('move', $event)">移动到…</button><button type="button" @click="action('copy', $event)">复制分支</button><button type="button" @click="action('paste', $event)">粘贴为子主题</button><button type="button" @click="action('style', $event)">主题样式…</button><button type="button" @click="action('link', $event)">建立关联…</button><button type="button" class="map-destructive" @click="action('delete', $event)">删除所选分支</button><hr /></template>
      <template v-if="hasMaps"><button type="button" @click="action('balanced', $event)">{{ layout === 'balanced' ? '✓ ' : '' }}左右展开</button><button type="button" @click="action('right', $event)">{{ layout === 'right' ? '✓ ' : '' }}向右树</button><button type="button" @click="action('export-markdown', $event)"><Download :size="14" />导出 Markdown 大纲</button><button type="button" @click="action('export-png', $event)"><Download :size="14" />导出完整 PNG</button><button v-if="selected" type="button" @click="action('export-branch', $event)"><Download :size="14" />导出所选分支 PNG</button><hr /></template>
      <button v-if="hasMaps" type="button" @click="action('create', $event)"><Plus :size="14" />添加思维导图</button><button type="button" @click="action('import', $event)"><Upload :size="14" />导入 Markdown 大纲</button><button v-if="canConvert" type="button" @click="action('restructure', $event)">将选中内容整理成导图…</button>
    </div></details>
  </nav>
</template>
<style scoped>
